"use client";

/**
 * NivoViewer: Universal 3D Experience Component
 * Compatible with React, Next.js (App & Pages Router), and Astro.
 * Generated by Nivo 3D Studio (https://nivo.jonave.in)
 */

import React, { useEffect, useState, useRef, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, useGLTF, useAnimations } from '@react-three/drei';
import * as THREE from 'three';
import type { NivoSceneData, NivoSceneObject, NivoViewerProps } from './types';
import { resolveNivoAsset } from './assets';

function MeshRenderer({ obj }: { obj: NivoSceneObject }) {
  const meshRef = useRef<THREE.Mesh>(null);
  const { position, rotation, scale } = obj.transform;

  let GeometryComponent: any = 'boxGeometry';
  if (obj.meshType === 'sphere') GeometryComponent = 'sphereGeometry';
  else if (obj.meshType === 'cylinder') GeometryComponent = 'cylinderGeometry';
  else if (obj.meshType === 'plane') GeometryComponent = 'planeGeometry';
  else if (obj.meshType === 'torus') GeometryComponent = 'torusGeometry';
  else if (obj.meshType === 'cone') GeometryComponent = 'coneGeometry';
  else if (obj.meshType === 'icosahedron') GeometryComponent = 'icosahedronGeometry';

  return (
    <mesh
      ref={meshRef}
      position={position}
      rotation={rotation}
      scale={scale}
      visible={obj.visible !== false}
      castShadow
      receiveShadow
    >
      <GeometryComponent />
      <meshStandardMaterial
        color={obj.color || '#4F46E5'}
        roughness={obj.roughness ?? 0.4}
        metalness={obj.metalness ?? 0.2}
        wireframe={obj.wireframe ?? false}
        transparent={obj.transparent ?? false}
        opacity={obj.opacity ?? 1}
      />
    </mesh>
  );
}

function ModelRenderer({ obj }: { obj: NivoSceneObject }) {
  if (!obj.modelUrl) return null;
  const resolvedUrl = resolveNivoAsset(obj.modelUrl);
  const { scene, animations } = useGLTF(resolvedUrl);
  const cloned = React.useMemo(() => scene.clone(), [scene]);
  const { position, rotation, scale } = obj.transform;

  const { actions } = useAnimations(animations, cloned);
  useEffect(() => {
    if (animations && animations.length > 0) {
      const firstAction = actions[animations[0].name];
      firstAction?.reset().fadeIn(0.2).play();
    }
  }, [actions, animations]);

  return (
    <primitive
      object={cloned}
      position={position}
      rotation={rotation}
      scale={scale}
      visible={obj.visible !== false}
    />
  );
}

function LightRenderer({ obj }: { obj: NivoSceneObject }) {
  const { position } = obj.transform;
  const intensity = obj.intensity ?? 1;
  const color = obj.color || '#ffffff';

  if (obj.lightType === 'ambient') {
    return <ambientLight color={color} intensity={intensity} />;
  }
  if (obj.lightType === 'point') {
    return <pointLight position={position} color={color} intensity={intensity} castShadow />;
  }
  if (obj.lightType === 'spot') {
    return <spotLight position={position} color={color} intensity={intensity} castShadow />;
  }
  return <directionalLight position={position} color={color} intensity={intensity} castShadow />;
}

function SceneStage({ data, cameraControls }: { data: NivoSceneData; cameraControls: boolean }) {
  const nonWebObjects = (data.objects || []).filter(o => !o.isWebOnly && o.id !== 'defaultPageId');
  const hasLights = nonWebObjects.some(o => o.type === 'light');

  return (
    <>
      {!hasLights && (
        <>
          <ambientLight intensity={0.7} />
          <directionalLight position={[10, 10, 10]} intensity={1.2} castShadow />
        </>
      )}

      {nonWebObjects.map(obj => {
        if (obj.type === 'mesh') return <MeshRenderer key={obj.id} obj={obj} />;
        if (obj.type === 'model') return <ModelRenderer key={obj.id} obj={obj} />;
        if (obj.type === 'light') return <LightRenderer key={obj.id} obj={obj} />;
        return null;
      })}

      {cameraControls && (
        <OrbitControls
          makeDefault
          enableDamping
          dampingFactor={0.05}
          touches={{
            ONE: THREE.TOUCH.ROTATE,
            TWO: THREE.TOUCH.DOLLY_PAN,
          }}
        />
      )}
    </>
  );
}

export function NivoViewer({
  scene: initialScene,
  src,
  className,
  style,
  cameraControls = true,
  autoPlay = true,
  lazy = true,
  rootMargin = '200px',
  posterUrl,
  onLoad,
  fallback = null
}: NivoViewerProps) {
  void autoPlay;
  const [sceneData, setSceneData] = useState<NivoSceneData | null>(initialScene || null);
  const [loading, setLoading] = useState<boolean>(!initialScene && !!src);
  const [canvasKey, setCanvasKey] = useState<number>(0);
  const [isInViewport, setIsInViewport] = useState<boolean>(!lazy);
  const [isRendered, setIsRendered] = useState<boolean>(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!lazy || isInViewport) return;
    if (typeof IntersectionObserver === 'undefined') {
      setIsInViewport(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          setIsInViewport(true);
          observer.disconnect();
        }
      },
      { rootMargin }
    );
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [lazy, rootMargin, isInViewport]);

  useEffect(() => {
    if (initialScene) {
      setSceneData(initialScene);
      onLoad?.(initialScene);
    }
  }, [initialScene]);

  useEffect(() => {
    if (!src || initialScene) return;
    let isCancelled = false;
    setLoading(true);

    fetch(src)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}: Failed to fetch ${src}`);
        return res.json();
      })
      .then((data: NivoSceneData) => {
        if (!isCancelled) {
          setSceneData(data);
          setLoading(false);
          onLoad?.(data);
        }
      })
      .catch((err) => {
        if (!isCancelled) {
          console.error('[NivoViewer] Failed to load remote scene:', err);
          setLoading(false);
        }
      });

    return () => {
      isCancelled = true;
    };
  }, [src]);

  if (loading || !sceneData) {
    return (
      <div
        ref={containerRef}
        className={className}
        style={{
          width: '100%',
          height: '100%',
          minHeight: 400,
          position: 'relative',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'transparent',
          ...style
        }}
      >
        {posterUrl && (
          <img
            src={posterUrl}
            alt="Scene Preview Poster"
            style={{ width: '100%', height: '100%', objectFit: 'cover', position: 'absolute', inset: 0 }}
          />
        )}
        {fallback}
      </div>
    );
  }

  const activeCamera = sceneData.objects?.find(o => o.id === sceneData.activeCameraId || o.type === 'camera');
  const cameraPos = (activeCamera?.transform?.position as [number, number, number]) || [0, 2, 8];

  return (
    <div
      ref={containerRef}
      className={className}
      style={{
        width: '100%',
        height: '100%',
        minHeight: 400,
        position: 'relative',
        overflow: 'hidden',
        background: sceneData.globalEnvironment?.background || 'transparent',
        ...style
      }}
      data-nivo-generator="Nivo 3D Studio"
      data-nivo-version={sceneData.version || '2.0'}
    >
      {posterUrl && !isRendered && (
        <img
          src={posterUrl}
          alt="Scene Preview Poster"
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            position: 'absolute',
            top: 0,
            left: 0,
            zIndex: 1,
            pointerEvents: 'none',
            transition: 'opacity 0.4s ease'
          }}
        />
      )}
      {isInViewport ? (
        <Canvas
          key={canvasKey}
          camera={{ position: cameraPos, fov: 45 }}
          shadows
          dpr={[1, 2]}
          gl={{ antialias: true, alpha: true, powerPreference: 'default' }}
          onCreated={({ gl }) => {
            setIsRendered(true);
            const dom = gl.domElement;
            dom.addEventListener('webglcontextlost', (e) => {
              e.preventDefault();
              console.warn('[NivoViewer] WebGL context lost. Auto-recovering...');
            }, false);
            dom.addEventListener('webglcontextrestored', () => {
              console.info('[NivoViewer] WebGL context restored. Re-mounting Canvas.');
              setCanvasKey((prev) => prev + 1);
            }, false);
          }}
        >
          <Suspense fallback={null}>
            <SceneStage data={sceneData} cameraControls={cameraControls} />
          </Suspense>
        </Canvas>
      ) : (
        <div style={{ width: '100%', height: '100%', minHeight: 400 }} />
      )}
    </div>
  );
}

export default NivoViewer;
